const body=$json.body??$json;
const allowed=new Set(['bank_account_id','statement_lines']);
const exact=body&&typeof body==='object'&&!Array.isArray(body)&&Object.keys(body).every((key)=>allowed.has(key));
const bankAccountId=typeof body?.bank_account_id==='string'?body.bank_account_id.trim():'';
const rawLines=Array.isArray(body?.statement_lines)?body.statement_lines:[];
const statementLines=rawLines.map((line)=>({statementLineId:typeof line?.statement_line_id==='string'?line.statement_line_id.trim():'',sourceHash:typeof line?.source_hash==='string'?line.source_hash.trim():''}));
const valid=Boolean(exact&&bankAccountId&&statementLines.length&&statementLines.length<=500&&new Set(statementLines.map((line)=>line.statementLineId)).size===statementLines.length&&statementLines.every((line)=>line.statementLineId&&/^[a-f0-9]{64}$/.test(line.sourceHash)));
return [{json:{valid,bankAccountId,statementLines,error:valid?'':'bank_account_id and unique statement_lines with SHA-256 source hashes are required'}}];

const raw=$('Validate Annotation Request').first().json;
if(!raw.valid) return [{json:{response:{ok:false,annotations:[],message:raw.error}}}];
const hashes=new Map(raw.statementLines.map((line)=>[line.statementLineId,line.sourceHash]));
const rows=$input.all().map((item)=>item.json).filter((row)=>row&&hashes.get(String(row.statementLineId||''))===String(row.statementSourceHash||'')&&String(row.likelyDescription||'').trim());
rows.sort((a,b)=>Date.parse(String(b.reviewedAt||b.decidedAt||0))-Date.parse(String(a.reviewedAt||a.decidedAt||0)));
const seen=new Set(); const annotations=[];
for(const row of rows){const id=String(row.statementLineId);if(seen.has(id))continue;seen.add(id);annotations.push({statementLineId:id,sourceHash:String(row.statementSourceHash),likelyDescription:String(row.likelyDescription).slice(0,300),evidenceSummary:String(row.evidenceSummary||'').slice(0,400),reviewQuestion:String(row.reviewQuestion||'').slice(0,300),blockerReason:String(row.whatToCheck||'').slice(0,300),resultLane:String(row.resultLane||'likely'),readyInXero:String(row.readyInXero)==='yes',confidence:Number(row.confidence||0)});}
return [{json:{response:{ok:true,bankAccountId:raw.bankAccountId,annotations,xeroWrites:false,persistentOverlay:false}}}];
